<?php require 'header.php';$rows=is_array($training_plans??null)?$training_plans:array();$statuses=array(1=>'Bản nháp',2=>'Chờ phê duyệt',3=>'Đã phê duyệt',4=>'Đã công khai');$classes=array(1=>'secondary',2=>'warning',3=>'info',4=>'success');$uid=intval($_SESSION['user']['id']??0);$super=intval($current_admin_user->user_group??0)===1;$csrf=htmlspecialchars($admin_csrf_token??'',ENT_QUOTES,'UTF-8');?>
<div class="content container-fluid"><div class="page-header"><div class="row align-items-center"><div class="col"><h3 class="page-title">Kế hoạch đào tạo, tập huấn</h3><p class="text-muted">Quản lý dữ liệu hiển thị tại trang Đào tạo & tập huấn.</p></div><div class="col-auto"><a class="btn btn-primary" href="<?php echo XC_URL;?>/admin/trainings/add"><i class="fa-solid fa-plus me-1"></i>Thêm kế hoạch</a></div></div></div>
<div class="card"><div class="card-body"><form class="row g-2 mb-3"><div class="col-md-7"><input class="form-control" name="keyword" value="<?php echo htmlspecialchars($filter_keyword??'',ENT_QUOTES,'UTF-8');?>" placeholder="Tìm mã, tên hoặc đơn vị tổ chức..."></div><div class="col-md-3"><select class="form-select" name="status"><option value="0">Tất cả trạng thái</option><?php foreach($statuses as $k=>$v):?><option value="<?php echo $k;?>" <?php echo intval($filter_status??0)===$k?'selected':'';?>><?php echo $v;?></option><?php endforeach;?></select></div><div class="col-md-2 d-grid"><button class="btn btn-outline-primary">Lọc dữ liệu</button></div></form>
<div class="table-responsive"><table class="table table-hover align-middle"><thead><tr><th>Mã</th><th>Tên kế hoạch</th><th>Thời gian</th><th>Đơn vị tổ chức</th><th>Trạng thái</th><th>Tệp</th><th>Thao tác</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="7" class="text-center text-muted py-5">Chưa có kế hoạch đào tạo.</td></tr><?php endif;?><?php foreach($rows as $r):$st=intval($r->status);$owner=intval($r->created_by)===$uid||$super;?><tr><td><strong><?php echo htmlspecialchars($r->plan_code,ENT_QUOTES,'UTF-8');?></strong></td><td style="max-width:420px"><strong><?php echo htmlspecialchars($r->title,ENT_QUOTES,'UTF-8');?></strong><br><small class="text-muted"><?php echo htmlspecialchars($r->summary??'',ENT_QUOTES,'UTF-8');?></small></td><td><?php echo date('d/m/Y',strtotime($r->start_date));?> - <?php echo date('d/m/Y',strtotime($r->end_date));?></td><td><?php echo htmlspecialchars($r->organizer,ENT_QUOTES,'UTF-8');?></td><td><span class="badge bg-<?php echo $classes[$st]??'dark';?>"><?php echo $statuses[$st]??'Không xác định';?></span></td><td><?php echo !empty($r->attachment_path)?'<i class="fa-regular fa-file-pdf text-danger"></i>':'—';?></td><td class="text-nowrap"><?php if($st===1&&$owner):?><a class="btn btn-sm btn-outline-success" href="<?php echo XC_URL.'/admin/trainings/edit/'.intval($r->id);?>" title="Sửa"><i class="fa-regular fa-pen-to-square"></i></a> <button class="btn btn-sm btn-outline-secondary training-action" data-id="<?php echo intval($r->id);?>" data-action="submit" title="Gửi duyệt"><i class="fa-solid fa-paper-plane"></i></button> <button class="btn btn-sm btn-outline-danger training-delete" data-id="<?php echo intval($r->id);?>" title="Xóa"><i class="fa-regular fa-trash-can"></i></button><?php endif;?><?php if($st===2&&$owner):?> <button class="btn btn-sm btn-outline-warning training-action" data-id="<?php echo intval($r->id);?>" data-action="cancel_submit">Hủy gửi</button><?php endif;?><?php if($st===2&&!empty($can_activity_approve)):?> <button class="btn btn-sm btn-success training-action" data-id="<?php echo intval($r->id);?>" data-action="approve">Duyệt</button> <button class="btn btn-sm btn-outline-danger training-action" data-id="<?php echo intval($r->id);?>" data-action="return">Trả lại</button><?php endif;?><?php if($st===3&&!empty($can_activity_publish)):?> <button class="btn btn-sm btn-primary training-action" data-id="<?php echo intval($r->id);?>" data-action="publish">Công khai</button><?php endif;?><?php if($st===4&&!empty($can_activity_publish)):?> <button class="btn btn-sm btn-outline-secondary training-action" data-id="<?php echo intval($r->id);?>" data-action="unpublish">Hủy công khai</button><?php endif;?></td></tr><?php endforeach;?></tbody></table></div>
<?php if(($total_pages??1)>1):?><nav><ul class="pagination justify-content-center"><?php for($n=1;$n<=$total_pages;$n++):?><li class="page-item <?php echo $n===$page?'active':'';?>"><a class="page-link" href="?<?php echo http_build_query(array_merge($_GET,array('page'=>$n)));?>"><?php echo $n;?></a></li><?php endfor;?></ul></nav><?php endif;?></div></div></div>
<script>$(function(){function action(id,a,reason){$.post('<?php echo XC_URL;?>/api/trainingPlanWorkflow',{id:id,action:a,reason:reason||'',csrf_token:'<?php echo $csrf;?>'},function(r){if(r.status==200)location.reload();else Swal.fire('Lỗi',r.message,'error')},'json')}$('.training-action').click(function(){var a=$(this).data('action'),reason='';if(a==='return'){reason=prompt('Nhập lý do trả lại:')||'';if(!reason.trim())return}action($(this).data('id'),a,reason)});$('.training-delete').click(function(){var id=$(this).data('id');Swal.fire({icon:'warning',title:'Xóa kế hoạch?',showCancelButton:true,confirmButtonText:'Xóa',cancelButtonText:'Hủy'}).then(function(x){if(x.isConfirmed)$.post('<?php echo XC_URL;?>/api/trainingPlanDelete',{id:id,csrf_token:'<?php echo $csrf;?>'},function(r){if(r.status==200)location.reload();else Swal.fire('Lỗi',r.message,'error')},'json')})})});</script>
<?php require 'footer.php';?>
